/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDocumentStore } from './src/document-store.js';
{
 const store=createDocumentStore({a:'old',b:'new'}), events=[];
 const nav=createWorkspace({store,renderDocument:x=>events.push(x),onHandoff:x=>events.push(['handoff',x])});
 nav.open('a'); nav.edit('changed'); nav.open('b');
 assert.deepEqual(events.at(-2),['handoff',{id:'a',text:'changed'}]);
 assert.deepEqual(events.at(-1),{id:'b',text:'new'});
}
{
 const store=createDocumentStore({a:'A',b:'B',c:'C'}), events=[];
 const nav=createWorkspace({store,renderDocument:x=>events.push(x),onHandoff:(x,n)=>{if(x.id==='a')n.open('c')}});
 nav.open('a'); nav.open('b'); nav.edit('edited');
 assert.deepEqual(events.at(-1),{id:'c',text:'C'});
 assert.equal(store.read('c'),'edited'); assert.equal(store.read('b'),'B');
}
{
 const events=[]; const nav=createWorkspace({store:createDocumentStore({a:'A',b:'B'}),renderDocument:x=>events.push(x),onHandoff:(x,n)=>n.dispose()});
 nav.open('a'); nav.open('b'); assert.equal(events.at(-1),null);
}
console.log('handoff, redirect, edit ownership, and dispose checks passed');
EOF"

